  for(let i=0;i<34;i++){decor.push({x:rand(.17,.83),y:rand(.16,.88),kind:'grass',s:rand(.45,1.25),seed:Math.random()});}
  const clampActor=(v,min,max)=>clamp(v,min,max);
  function resize(){const r=frame.getBoundingClientRect();if(!r.width||!r.height)return;W=r.width;H=r.height;dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}
  new ResizeObserver(resize).observe(frame); window.addEventListener('resize',resize); resize();
  function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(lastToast);lastToast=setTimeout(()=>el.classList.remove('show'),1900);}
  function playTone(freq=240,duration=.08,type='sine'){if(!soundOn)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch(_){}}
  function nearestTarget(actor,range=1){let best=null,bestD=Infinity;for(const f of fighters){if(f===actor||!f.alive)continue;const d=dist(actor,f);if(d<bestD&&d<range){best=f;bestD=d;}}return best;}
  function dist(a,b){const dx=(a.x-b.x)*W,dy=(a.y-b.y)*H;return Math.hypot(dx,dy)/Math.min(W,H);}
  function logEvent(text){const log=$('battleLog');const empty=log.querySelector('.empty-log');if(empty)empty.remove();const node=document.createElement('div');node.className='log-entry';const t=String(Math.floor(elapsed)).padStart(2,'0');node.innerHTML=`<span class="log-time">${t}s</span>${text}`;log.prepend(node);while(log.children.length>5)log.lastElementChild.remove();}
  function feed(killer,victim){const feed=$('killFeed'),node=document.createElement('div');node.className='feed-line';node.innerHTML=`<span class="feed-gold">✦</span> <b>${killer.id==='player'?'Vos':names[killer.id]}</b><span> derrotó a </span><b>${victim.id==='player'?'vos':names[victim.id]}</b>`;feed.prepend(node);while(feed.children.length>3)feed.lastElementChild.remove();}
  function kill(victim,attacker){if(!victim.alive)return;victim.hp=0;victim.alive=false;victim.respawn=3.0;victim.block=false;if(attacker){attacker.kills++;feed(attacker,victim);const playerKill=attacker.id==='player';const victimPlayer=victim.id==='player';logEvent(playerKill?`<b>Conseguiste una baja</b> contra ${names[victim.id]}.`:victimPlayer?`<b>${names[attacker.id]}</b> te derrotó.`:`${names[attacker.id]} derrotó a ${names[victim.id]}.`);if(playerKill){playTone(480,.18,'triangle');toast('¡Baja conseguida!');}else playTone(150,.12,'sawtooth');}
    if(victim.id==='player'){invuln=0;toast('Caíste en combate. Volvés en un instante…');}
    refreshHud();if(attacker&&attacker.kills>=5)endMatch(attacker.id==='player');}
  function respawn(f){f.alive=true;f.hp=100;f.mana=74;f.slow=0;f.flash=.8;f.block=false;const spots=[[.49,.62],[.31,.39],[.69,.4],[.72,.69]];const p=spots[1+Math.floor(Math.random()*3)];if(f.id==='player'){f.x=.49;f.y=.62;invuln=1.7;}else{f.x=rand(.24,.76);f.y=rand(.25,.78);}f.tx=f.x;f.ty=f.y;}
  function dealDamage(target,amount,attacker,kind){if(!target.alive)return;let dmg=amount;if(target.block)dmg*=.42;if(target.id==='player'&&invuln>0)dmg=0;target.hp=Math.max(0,target.hp-dmg);target.flash=.19;target.lastAttacker=attacker.id;target.cast=.33;target.castType=kind||'hit';if(target.hp<=0)kill(target,attacker);playTone(kind==='frost'?530:kind==='ult'?320:185,.07,'triangle');refreshHud();}
  function castSpell(index,actor=fighters[0]){if(gameOver||paused||!actor.alive)return;if(index<0||index>3)return;const data=spellsData[index];if(actor.id==='player'&&cooldowns[index]>0)return;if(actor.mana<data.cost){if(actor.id==='player')toast('No tenés suficiente maná');return;}actor.mana-=data.cost;if(actor.id==='player')cooldowns[index]=data.cd;const target=nearestTarget(actor,data.range);
    if(index===0){if(target){dealDamage(target,data.damage,actor,'slash');target.slow=Math.max(target.slow,.12);actor.cast=.2;actor.castType='slash';}else if(actor.id==='player')toast('Acercate a un rival para atacar');}
    if(index===1){if(target){dealDamage(target,data.damage,actor,'frost');target.slow=1.45;actor.cast=.45;actor.castType='frost';}else if(actor.id==='player')toast('No hay rivales a alcance');}
    if(index===2){if(target){const dx=target.x-actor.x,dy=target.y-actor.y,d=Math.hypot(dx,dy)||1;actor.x=clamp(actor.x+dx/d*.11,arenaBounds.left,arenaBounds.right);actor.y=clamp(actor.y+dy/d*.11,arenaBounds.top,arenaBounds.bottom);dealDamage(target,data.damage,actor,'charge');actor.cast=.42;actor.castType='charge';}else if(actor.id==='player')toast('No hay rivales a alcance de carga');}
    if(index===3){let hit=0;for(const f of fighters){if(f!==actor&&f.alive&&dist(actor,f)<data.range){dealDamage(f,data.damage,actor,'ult');hit++;}}actor.cast=.6;actor.castType='ult';if(!hit&&actor.id==='player')toast('La tormenta no alcanzó a nadie');}
    if(actor.id==='player')playTone([300,650,400,220][index],.16,index===1?'sine':'triangle');refreshHud();}
  function basicAttack(actor=fighters[0]){if(!actor.alive||gameOver||paused)return;const target=nearestTarget(actor,.13);if(target){dealDamage(target,9,actor,'hit');actor.attackCd=.55;actor.dir=target.x>=actor.x?1:-1;actor.cast=.17;actor.castType='slash';}else if(actor.id==='player')toast('Acercate a un rival para atacar');}
  function usePotion(){const p=fighters[0];if(potionCd>0)return;if(potionCount<=0){toast('No te quedan pociones');return;}if(p.hp>=100&&p.mana>=100){toast('Ya estás en plena forma');return;}potionCount--;potionCd=1.2;p.hp=Math.min(100,p.hp+42);p.mana=Math.min(100,p.mana+36);playTone(620,.2,'sine');toast('Poción utilizada · +vida y maná');refreshHud();}
  function movePlayer(dt){const p=fighters[0];let x=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+joystick.dx;let y=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+joystick.dy;const l=Math.hypot(x,y);if(l>1){x/=l;y/=l;}if(l>.05){const speed=joystick.active||isTouch? .29:.32;p.x=clampActor(p.x+x*speed*dt,arenaBounds.left,arenaBounds.right);p.y=clampActor(p.y+y*speed*dt,arenaBounds.top,arenaBounds.bottom);p.walk+=dt*11;if(x)p.dir=Math.sign(x);}if(blockHeld){p.block=true;}else p.block=false;}
  let isTouch=false;
  function updateBots(dt){for(let i=1;i<fighters.length;i++){const f=fighters[i];if(!f.alive)continue;f.aiTimer-=dt;let target=nearestTarget(f,.9);if(target){const d=dist(f,target);if(d>.082){const dx=(target.x-f.x)*W,dy=(target.y-f.y)*H,l=Math.hypot(dx,dy)||1;const speed=f.slow>0?.11:.19;f.x=clamp(f.x+dx/l*speed*dt,arenaBounds.left,arenaBounds.right);f.y=clamp(f.y+dy/l*speed*dt,arenaBounds.top,arenaBounds.bottom);f.walk+=dt*8;f.dir=dx>=0?1:-1;}else if(f.attackCd<=0){if(Math.random()<.28&&f.mana>24)castSpell(Math.random()<.7?1:0,f);else{dealDamage(target,8,f,'hit');f.attackCd=.7;}}if(f.aiTimer<=0){if(f.mana>47&&Math.random()<.08)castSpell(3,f);else if(f.mana>24&&Math.random()<.22)castSpell(1,f);else if(Math.random()<.19)castSpell(2,f);else if(d<.13)castSpell(0,f);f.aiTimer=rand(.55,1.35);}}else if(f.aiTimer<=0){f.tx=rand(.2,.8);f.ty=rand(.2,.82);f.aiTimer=rand(1.3,3);}
      if(!target){const dx=f.tx-f.x,dy=f.ty-f.y,l=Math.hypot(dx*W,dy*H);if(l>13){f.x+=dx/l*.15*dt;f.y+=dy/l*.15*dt;f.walk+=dt*5;f.dir=dx>=0?1:-1;}}
    }}
  function update(dt){if(gameOver||paused)return;elapsed+=dt;remaining=Math.max(0,remaining-dt);const player=fighters[0];movePlayer(dt);updateBots(dt);
    for(const f of fighters){if(f.attackCd>0)f.attackCd-=dt;if(f.slow>0)f.slow-=dt;if(f.flash>0)f.flash-=dt;if(f.cast>0)f.cast-=dt;if(!f.alive){f.respawn-=dt;if(f.respawn<=0)respawn(f);}else{f.mana=Math.min(100,f.mana+dt*2.7);}}
    cooldowns=cooldowns.map(v=>Math.max(0,v-dt));potionCd=Math.max(0,potionCd-dt);if(remaining===0)endMatch([...fighters].sort((a,b)=>b.kills-a.kills)[0]?.id==='player');refreshHud();}

